   106	    const styles = useThemeStyles();
   107	    const theme = useTheme();
   108	    const {isSmallScreenWidth} = useResponsiveLayout();
   109	    const selectedItemIndex = useRef<number | null>(null);
   110	
   111	    const [currentMenuItems, setCurrentMenuItems] = useState(menuItems);
   112	    const [enteredSubMenuIndexes, setEnteredSubMenuIndexes] = useState<number[]>([]);
   113	
   114	    const [focusedIndex, setFocusedIndex] = useArrowKeyFocusManager({initialFocusedIndex: -1, maxIndex: currentMenuItems.length - 1, isActive: isVisible});
   115	
   116	    const selectItem = (index: number) => {
   117	        const selectedItem = currentMenuItems[index];
   118	        if (selectedItem?.subMenuItems) {
   119	            setCurrentMenuItems([...selectedItem.subMenuItems]);
   120	            setEnteredSubMenuIndexes([...enteredSubMenuIndexes, index]);
   121	            setFocusedIndex(-1);
   122	        } else {
   123	            selectedItemIndex.current = index;
   124	            onItemSelected(selectedItem, index);
   125	        }
   126	    };
   127	
   128	    const getPreviousSubMenu = () => {
   129	        let currentItems = menuItems;
   130	        for (let i = 0; i < enteredSubMenuIndexes.length - 1; i++) {
   131	            const nextItems = currentItems[enteredSubMenuIndexes[i]].subMenuItems;
   132	            if (!nextItems) {
   133	                return currentItems;
   134	            }
   135	            currentItems = nextItems;
   136	        }
   137	        return currentItems;
   138	    };
   139	
   140	    const renderBackButtonItem = () => {
   141	        const previousMenuItems = getPreviousSubMenu();
   142	        const previouslySelectedItem = previousMenuItems[enteredSubMenuIndexes[enteredSubMenuIndexes.length - 1]];
   143	        const hasBackButtonText = !!previouslySelectedItem.backButtonText;
   144	
   145	        return (
   146	            <MenuItem
   147	                key={previouslySelectedItem.text}
   148	                icon={Expensicons.BackArrow}
   149	                iconFill={theme.icon}
   150	                style={hasBackButtonText ? styles.pv0 : undefined}
   151	                title={hasBackButtonText ? previouslySelectedItem.backButtonText : previouslySelectedItem.text}
   152	                titleStyle={hasBackButtonText ? styles.createMenuHeaderText : undefined}
   153	                shouldShowBasicTitle={hasBackButtonText}
   154	                shouldCheckActionAllowedOnPress={false}
   155	                description={previouslySelectedItem.description}
   156	                onPress={() => {
   157	                    setCurrentMenuItems(previousMenuItems);
   158	                    setFocusedIndex(-1);
   159	                    enteredSubMenuIndexes.splice(-1);
   160	                }}
   161	            />
   162	        );
   163	    };
   164	
   165	    useKeyboardShortcut(
   166	        CONST.KEYBOARD_SHORTCUTS.ENTER,
   167	        () => {
   168	            if (focusedIndex === -1) {
   169	                return;
   170	            }
