   181	            selectedItemIndex.current = null;
   182	        }
   183	    };
   184	
   185	    useEffect(() => {
   186	        if (menuItems.length === 0) {
   187	            return;
   188	        }
   189	        setEnteredSubMenuIndexes([]);
   190	        setCurrentMenuItems(menuItems);
   191	    }, [menuItems]);
   192	
   193	    return (
   194	        <PopoverWithMeasuredContent
   195	            anchorPosition={anchorPosition}
   196	            anchorRef={anchorRef}
   197	            anchorAlignment={anchorAlignment}
   198	            onClose={() => {
   199	                setCurrentMenuItems(menuItems);
   200	                setEnteredSubMenuIndexes([]);
   201	                onClose();
   202	            }}
   203	            isVisible={isVisible}
   204	            onModalHide={onModalHide}
   205	            animationIn={animationIn}
   206	            animationOut={animationOut}
   207	            animationInTiming={animationInTiming}
   208	            disableAnimation={disableAnimation}
   209	            fromSidebarMediumScreen={fromSidebarMediumScreen}
   210	            withoutOverlay={withoutOverlay}
   211	            shouldSetModalVisibility={shouldSetModalVisibility}
   212	            shouldEnableNewFocusManagement={shouldEnableNewFocusManagement}
   213	        >
   214	            <FocusTrapForModal active={isVisible}>
   215	                <View style={isSmallScreenWidth ? {} : styles.createMenuContainer}>
   216	                    {!!headerText && enteredSubMenuIndexes.length === 0 && <Text style={[styles.createMenuHeaderText, styles.ph5, styles.pv3]}>{headerText}</Text>}
   217	                    {enteredSubMenuIndexes.length > 0 && renderBackButtonItem()}
   218	                    {currentMenuItems.map((item, menuIndex) => (
   219	                        <FocusableMenuItem
   220	                            key={item.text}
   221	                            icon={item.icon}
   222	                            iconWidth={item.iconWidth}
   223	                            iconHeight={item.iconHeight}
   224	                            iconFill={item.iconFill}
   225	                            contentFit={item.contentFit}
   226	                            title={item.text}
   227	                            shouldCheckActionAllowedOnPress={false}
   228	                            description={item.description}
   229	                            numberOfLinesDescription={item.numberOfLinesDescription}
   230	                            onPress={() => selectItem(menuIndex)}
   231	                            focused={focusedIndex === menuIndex}
   232	                            displayInDefaultIconColor={item.displayInDefaultIconColor}
   233	                            shouldShowRightIcon={item.shouldShowRightIcon}
   234	                            iconRight={item.iconRight}
   235	                            shouldPutLeftPaddingWhenNoIcon={item.shouldPutLeftPaddingWhenNoIcon}
   236	                            label={item.label}
   237	                            isLabelHoverable={item.isLabelHoverable}
   238	                            floatRightAvatars={item.floatRightAvatars}
   239	                            floatRightAvatarSize={item.floatRightAvatarSize}
   240	                            shouldShowSubscriptRightAvatar={item.shouldShowSubscriptRightAvatar}
   241	                            disabled={item.disabled}
   242	                            onFocus={() => setFocusedIndex(menuIndex)}
   243	                            success={item.success}
   244	                            containerStyle={item.containerStyle}
   245	                        />
   246	                    ))}
   247	                </View>
   248	            </FocusTrapForModal>
   249	        </PopoverWithMeasuredContent>
   250	    );
   251	}
   252	
   253	PopoverMenu.displayName = 'PopoverMenu';
   254	
   255	export default React.memo(
   256	    PopoverMenu,
   257	    (prevProps, nextProps) =>
   258	        !lodashIsEqual(prevProps.menuItems, nextProps.menuItems) &&
   259	        prevProps.isVisible === nextProps.isVisible &&
   260	        lodashIsEqual(prevProps.anchorPosition, nextProps.anchorPosition) &&
   261	        prevProps.anchorRef === nextProps.anchorRef &&
   262	        prevProps.headerText === nextProps.headerText &&
   263	        prevProps.fromSidebarMediumScreen === nextProps.fromSidebarMediumScreen &&
   264	        lodashIsEqual(prevProps.anchorAlignment, nextProps.anchorAlignment) &&
   265	        prevProps.animationIn === nextProps.animationIn &&
   266	        prevProps.animationOut === nextProps.animationOut &&
   267	        prevProps.animationInTiming === nextProps.animationInTiming &&
   268	        prevProps.disableAnimation === nextProps.disableAnimation &&
   269	        prevProps.withoutOverlay === nextProps.withoutOverlay &&
   270	        prevProps.shouldSetModalVisibility === nextProps.shouldSetModalVisibility,
   271	);
   272	export type {PopoverMenuItem, PopoverMenuProps};
